import { ParentComponent } from "solid-js";

import { AudioContextProvider } from "#core/ui-next/components/audio-context-provider.jsx";
import { CloseButton } from "#core/ui-next/components/close-button.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

export interface CreateGamePopupFrameProps {
	class?: string;
	onClose: () => void;
}

const CreateGamePopupFrameComponent: ParentComponent<CreateGamePopupFrameProps> = (props) => {
	return (
		<div class="img-frame-f1 relative h-full flex flex-row min-w-200 pointer-events-auto">
			<div class="img-frame-filigree absolute top-4 left-4 size-64" />
			<div class="img-frame-filigree absolute top-4 right-4 size-64 -scale-x-100" />
			<div class={`absolute inset-0  ${props.class ?? ""}`}>{props.children}</div>
			<AudioContextProvider segment="CloseButton">
				<CloseButton
					onActivate={props.onClose}
					class="absolute top-4 right-4"
				/>
			</AudioContextProvider>
		</div>
	);
};

export const CreateGamePopupFrame = ComponentRegistry.register({
	name: "CreateGamePopupFrame",
	createInstance: CreateGamePopupFrameComponent,
	styles: [],
});
